const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

  if (req.method === "GET" && url.pathname === "/health") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ status: "ok" }));
    return;
  }

  // Better Auth endpoints (sign-in, sign-out, session)
  if (url.pathname === "/api/auth" || url.pathname.startsWith("/api/auth/")) {
    try {
      await authHandler(req, res);
    } catch (error: unknown) {
      console.error("Auth request failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Auth failed" });
      else res.end();
    }
    return;
  }

  // Current user
  if (url.pathname === "/api/me") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, { user });
    return;
  }

  // Web chat API
  if (url.pathname === "/api/agents") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, listAgents(user));
    return;
  }

  const capsMatch = url.pathname.match(/^\/api\/agents\/([^/]+)\/caps$/);
  if (capsMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleAgentCaps(decodeURIComponent(capsMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Agent caps request failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Agent caps request failed" });
      else res.end();
    }
    return;
  }

  const historyMatch = url.pathname.match(/^\/api\/chat\/([^/]+)\/history$/);
  if (historyMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChatHistory(decodeURIComponent(historyMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Chat history failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat history failed" });
      else res.end();
    }
    return;
  }

  const neatlogsUsageMatch = url.pathname.match(/^\/api\/chat\/([^/]+)\/messages\/([^/]+)\/neatlogs-usage$/);
  if (neatlogsUsageMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleNeatlogsUsage(decodeURIComponent(neatlogsUsageMatch[1]), decodeURIComponent(neatlogsUsageMatch[2]), req, res, user);
    } catch (error: unknown) {
      console.error("Neatlogs usage request failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Neatlogs usage request failed" });
      else res.end();
    }
    return;
  }

  const chatMatch = url.pathname.match(/^\/api\/chat\/([^/]+)$/);
  if (chatMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChat(decodeURIComponent(chatMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Web chat failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat failed" });
      else res.end();
    }
    return;
  }

  // cfo.ai OAuth connection (per signed-in user)
  if (url.pathname.startsWith("/api/cfo/")) {
    const route = url.pathname.slice("/api/cfo/".length);
    const allowed: Record<string, string[]> = {
      connect: ["GET"],
      callback: ["GET"],
      status: ["GET"],
      disconnect: ["POST", "DELETE"],
    };
    const methods = allowed[route];
    if (!methods) {
      res.writeHead(404).end();
      return;
    }
    if (!methods.includes(req.method ?? "")) {
      res.writeHead(405, { allow: methods.join(", ") }).end();
      return;
    }
